#!/usr/bin/env python3
"""Compare two directory trees for exact structure + content equality."""
import hashlib
import os
import sys

def tree_map(root):
    files, dirs = {}, set()
    for dirpath, dirnames, filenames in os.walk(root):
        rel_d = os.path.relpath(dirpath, root)
        if rel_d != ".":
            dirs.add(rel_d)
        for fn in filenames:
            p = os.path.join(dirpath, fn)
            rel = fn if rel_d == "." else os.path.join(rel_d, fn)
            if os.path.islink(p):
                files[rel] = ("symlink", os.readlink(p))
            else:
                h = hashlib.sha256()
                with open(p, "rb") as f:
                    for chunk in iter(lambda: f.read(1024 * 1024), b""):
                        h.update(chunk)
                files[rel] = ("file", os.path.getsize(p), h.hexdigest())
    return files, dirs

def main():
    a, b = sys.argv[1], sys.argv[2]
    fa, da = tree_map(a)
    fb, db = tree_map(b)
    ok = True
    if set(fa) != set(fb):
        ok = False
        only_a = set(fa).difference(fb)
        only_b = set(fb).difference(fa)
        if only_a:
            print(f"files only in {a}: {sorted(only_a)[:5]} ({len(only_a)} total)")
        if only_b:
            print(f"files only in {b}: {sorted(only_b)[:5]} ({len(only_b)} total)")
    for k in sorted(set(fa).intersection(fb)):
        if fa[k] != fb[k]:
            ok = False
            print(f"content mismatch: {k}: {fa[k][:2]} vs {fb[k][:2]}")
    if da != db:
        ok = False
        only_a = da.difference(db)
        only_b = db.difference(da)
        if only_a:
            print(f"dirs only in {a}: {sorted(only_a)[:5]} ({len(only_a)} total)")
        if only_b:
            print(f"dirs only in {b}: {sorted(only_b)[:5]} ({len(only_b)} total)")
    if ok:
        print(f"OK: trees identical ({len(fa)} files, {len(da)} dirs)")
    else:
        print("FAILED: trees differ")
        sys.exit(1)

main()
